{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "The closest structural analogue has an absolute oral bioavailability of approximately 20–25%, meeting the ≥20% threshold and supporting high bioavailability despite being borderline.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A cyclopentyl-containing kinase inhibitor analogue was predicted to have 80% human oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A piperazine-aniline-aminopyrimidine analogue showed 77% absolute oral bioavailability in healthy volunteers in the fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "The same piperazine-aniline-aminopyrimidine analogue showed 57% absolute oral bioavailability in the fasted state, still well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Brigatinib, sharing the piperazine-aniline-aminopyrimidine core, had approximately 46% oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brepocitinib, a related heteroaromatic kinase inhibitor, had 75% absolute oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib, containing a piperazine-aniline-pyrimidine motif, had 98% absolute oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fasudil, a piperazine-containing heteroaromatic drug, had 69% absolute oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Niraparib, a related heteroaromatic drug, had approximately 73% absolute oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Risdiplam, a heteroaromatic drug with a similar oral exposure profile, has high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Although the physicochemical prior predicts low absorption due to ionization and high polar surface area, multiple transferable experimental analogues with similar piperazine-aniline-aminopyrimidine scaffolds show absolute oral bioavailability well above 20%, and the closest analogue is borderline but still meets the threshold. The experimental evidence therefore supports a high bioavailability prediction.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule itself.",
    "The closest analogue C08 is borderline at 20–25%, adding some uncertainty.",
    "No query-specific permeability, transport, or efflux data are available to resolve the physicochemical absorption concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

